282→// condenseAndFinalizeSession condenses the session to permanent storage and transitions it to IDLE.
283→// Returns the checkpoint ID string and any condensation error.
284→func condenseAndFinalizeSession(ctx context.Context, strat *strategy.ManualCommitStrategy, sessionID string) (string, error) {
285→	var checkpointIDStr string
286→	var condenseErr error
287→	if err := strat.CondenseSessionByID(ctx, sessionID); err != nil {
288→		logging.Warn(ctx, "failed to condense session", "error", err, "session_id", sessionID)
289→		condenseErr = err
290→	}
291→
292→	// Single load serves both checkpoint ID extraction and finalization
293→	state, loadErr := strategy.LoadSessionState(ctx, sessionID)
294→	if loadErr != nil {
295→		logging.Warn(ctx, "failed to load session state after condensation", "error", loadErr, "session_id", sessionID)
296→		return checkpointIDStr, condenseErr
297→	}
298→	if state == nil {
299→		return checkpointIDStr, condenseErr
300→	}
301→
302→	if condenseErr == nil {
303→		checkpointIDStr = state.LastCheckpointID.String()
304→	}
305→
306→	now := time.Now()
307→	state.LastInteractionTime = &now
308→	if transErr := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
309→		logging.Warn(ctx, "failed to transition session to idle", "error", transErr, "session_id", sessionID)
310→	}
311→	if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
312→		logging.Warn(ctx, "failed to save session state after transition", "error", saveErr, "session_id", sessionID)
313→	}
314→
315→	return checkpointIDStr, condenseErr
316→}
