379→// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
380→// Supports both JSONL format (Claude Code, Cursor, OpenCode) and Gemini JSON format.
381→func extractFirstPromptFromTranscript(data []byte) string {
382→	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
383→	lines, err := transcript.ParseFromBytes(data)
384→	if err == nil {
385→		for _, line := range lines {
386→			if line.Type == transcript.TypeUser {
387→				prompt := extractTextFromMessage(line.Message)
388→				if prompt != "" {
389→					return prompt
390→				}
391→			}
392→		}
393→	}
394→
395→	// Fallback: try Gemini JSON format {"messages": [...]}
396→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
397→		return prompts[0]
398→	}
399→
400→	return ""
401→}
402→
403→// extractTextFromMessage extracts the text content from a transcript message.
404→func extractTextFromMessage(msg json.RawMessage) string {
405→	// Try string content first (simple user messages)
406→	var simple struct {
407→		Content string `json:"content"`
408→	}
409→	if err := json.Unmarshal(msg, &simple); err == nil && simple.Content != "" {
410→		return simple.Content
411→	}
412→
413→	// Try array content (messages with tool results, text blocks, etc.)
414→	var array struct {
415→		Content []struct {
416→			Type string `json:"type"`
417→			Text string `json:"text"`
418→		} `json:"content"`
419→	}
420→	if err := json.Unmarshal(msg, &array); err == nil {
421→		for _, block := range array.Content {
422→			if block.Type == "text" && block.Text != "" {
423→				return block.Text
424→			}
425→		}
426→	}
427→
428→	return ""
429→}
430→
431→// normalizeGeminiTranscript re-serializes a Gemini JSON transcript so that all
432→// content fields are plain strings. Gemini user messages store content as
433→// [{"text":"..."}] arrays, but the UI expects string content. Parsing through
434→// geminicli.ParseTranscript normalizes this via GeminiMessage.UnmarshalJSON.
435→func normalizeGeminiTranscript(data []byte) ([]byte, error) {
436→	parsed, err := geminicli.ParseTranscript(data)
437→	if err != nil {
438→		return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
439→	}
440→	normalized, err := json.MarshalIndent(parsed, "", "  ")
441→	if err != nil {
442→		return nil, fmt.Errorf("failed to re-serialize Gemini transcript: %w", err)
443→	}
444→	return normalized, nil
445→}
446→
447→// countUserTurns counts real user prompts in a transcript (excluding tool_result messages).
448→// Supports both JSONL format (Claude Code, Cursor) and Gemini JSON format.
449→func countUserTurns(data []byte) int {
450→	// Try JSONL format first — use extractTextFromMessage to distinguish
451→	// real user prompts from tool_result messages (both have type "user").
452→	lines, err := transcript.ParseFromBytes(data)
453→	if err == nil {
454→		count := 0
455→		for _, line := range lines {
456→			if line.Type == transcript.TypeUser {
457→				if extractTextFromMessage(line.Message) != "" {
458→					count++
459→				}
460→			}
461→		}
462→		if count > 0 {
463→			return count
464→		}
465→	}
466→
467→	// Fallback: Gemini JSON format
468→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil {
469→		return len(prompts)
470→	}
471→
472→	return 0
473→}
474→
475→// extractModelFromTranscript extracts the model name from a JSONL transcript.
476→// Best-effort: returns empty string if the transcript format doesn't include model info
477→// (e.g., Gemini stores model info in hook events, not the transcript).
478→func extractModelFromTranscript(data []byte) string {
479→	lines, err := transcript.ParseFromBytes(data)
480→	if err != nil {
481→		return ""
482→	}
483→
484→	for _, line := range lines {
485→		if line.Type != transcript.TypeAssistant {
486→			continue
487→		}
488→		var msg struct {
489→			Model string `json:"model"`
490→		}
491→		if err := json.Unmarshal(line.Message, &msg); err == nil && msg.Model != "" {
492→			return msg.Model
493→		}
494→	}
495→	return ""
496→}
497→
498→// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
499→// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
500→// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
501→// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
502→func estimateSessionDuration(data []byte) int64 {
503→	type timestamped struct {
504→		Timestamp string `json:"timestamp"`
505→	}
506→
507→	var first, last time.Time
508→	for _, rawLine := range bytes.Split(data, []byte("\n")) {
509→		if len(rawLine) == 0 {
510→			continue
511→		}
512→		var ts timestamped
513→		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
514→			continue
515→		}
516→		parsed, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
517→		if err != nil {
518→			parsed, err = time.Parse(time.RFC3339, ts.Timestamp)
519→			if err != nil {
520→				continue
521→			}
522→		}
523→		if first.IsZero() {
524→			first = parsed
525→		}
526→		last = parsed
527→	}
528→
529→	if first.IsZero() || last.IsZero() || !last.After(first) {
530→		return 0
531→	}
532→	return last.Sub(first).Milliseconds()
533→}
