 20→func TestAttach_MissingSessionID(t *testing.T) {
 21→	t.Parallel()
 22→
 23→	cmd := newAttachCmd()
 24→	cmd.SetArgs([]string{})
 25→
 26→	var out bytes.Buffer
 27→	cmd.SetOut(&out)
 28→	cmd.SetErr(&out)
 29→
 30→	err := cmd.Execute()
 31→	if err == nil {
 32→		t.Fatal("expected error for missing session ID")
 33→	}
