 36→func TestAttach_TranscriptNotFound(t *testing.T) {
 37→	tmpDir := t.TempDir()
 38→	testutil.InitRepo(t, tmpDir)
 39→	testutil.WriteFile(t, tmpDir, "init.txt", "init")
 40→	testutil.GitAdd(t, tmpDir, "init.txt")
 41→	testutil.GitCommit(t, tmpDir, "init")
 42→	t.Chdir(tmpDir)
 43→
 44→	// Enable entire
 45→	enableEntire(t, tmpDir)
 46→
 47→	// Set up a fake Claude project dir that's empty
 48→	claudeDir := t.TempDir()
 49→	t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", claudeDir)
 50→
