 84→// ResolveSessionFile returns the path to a Gemini session file.
 85→// Gemini names files as session-<date>-<shortid>.json where shortid is the first 8 chars
 86→// of the session UUID. This searches for an existing file matching the pattern, falling
 87→// back to constructing a filename matching Gemini's convention if no match is found.
 88→func (g *GeminiCLIAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 89→	// Try to find existing file matching Gemini's naming convention:
 90→	// session-*-<first8chars>.json
 91→	shortID := agentSessionID
 92→	if len(shortID) > 8 {
 93→		shortID = shortID[:8]
 94→	}
 95→
 96→	pattern := filepath.Join(sessionDir, "session-*-"+shortID+".json")
 97→	matches, err := filepath.Glob(pattern)
 98→	if err == nil && len(matches) > 0 {
 99→		// Return the most recent match (last alphabetically, since date is in the name)
100→		return matches[len(matches)-1]
101→	}
102→
103→	// Fallback: construct filename matching Gemini's convention: session-<timestamp>-<id[:8]>.json
104→	timestamp := time.Now().UTC().Format("2006-01-02T15-04")
105→	return filepath.Join(sessionDir, "session-"+timestamp+"-"+shortID+".json")
106→}
107→
108→// GetSessionDir returns the directory where Gemini stores session transcripts.
109→// Gemini stores sessions in ~/.gemini/tmp/<project-hash>/chats/
110→func (g *GeminiCLIAgent) GetSessionDir(repoPath string) (string, error) {
111→	// Check for test environment override
112→	if override := os.Getenv("ENTIRE_TEST_GEMINI_PROJECT_DIR"); override != "" {
113→		return override, nil
114→	}
115→
116→	homeDir, err := os.UserHomeDir()
117→	if err != nil {
118→		return "", fmt.Errorf("failed to get home directory: %w", err)
119→	}
120→
121→	// Gemini uses a SHA256 hash of the project path for the directory name
122→	projectDir := GetProjectHash(repoPath)
123→	return filepath.Join(homeDir, ".gemini", "tmp", projectDir, "chats"), nil
124→}
125→
126→// ReadSession reads a session from Gemini's storage (JSON transcript file).
127→// The session data is stored in NativeData as raw JSON bytes.
128→func (g *GeminiCLIAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
129→	if input.SessionRef == "" {
130→		return nil, errors.New("session reference (transcript path) is required")
131→	}
132→
133→	// Read the raw JSON file
134→	data, err := os.ReadFile(input.SessionRef)
135→	if err != nil {
136→		return nil, fmt.Errorf("failed to read transcript: %w", err)
137→	}
138→
139→	// Parse to extract computed fields
140→	modifiedFiles, err := ExtractModifiedFiles(data)
141→	if err != nil {
142→		// Non-fatal: we can still return the session without modified files
143→		modifiedFiles = nil
144→	}
145→
146→	return &agent.AgentSession{
147→		SessionID:     input.SessionID,
148→		AgentName:     g.Name(),
149→		SessionRef:    input.SessionRef,
150→		StartTime:     time.Now(),
151→		NativeData:    data,
152→		ModifiedFiles: modifiedFiles,
153→	}, nil
154→}
155→
156→// WriteSession writes a session to Gemini's storage (JSON transcript file).
157→// Uses the NativeData field which contains raw JSON bytes.
158→func (g *GeminiCLIAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
159→	if session == nil {
160→		return errors.New("session is nil")
161→	}
162→
163→	// Verify this session belongs to Gemini CLI
164→	if session.AgentName != "" && session.AgentName != g.Name() {
165→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, g.Name())
166→	}
167→
168→	if session.SessionRef == "" {
169→		return errors.New("session reference (transcript path) is required")
170→	}
171→
172→	if len(session.NativeData) == 0 {
173→		return errors.New("session has no native data to write")
174→	}
175→
176→	// Write the raw JSON data
177→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
178→		return fmt.Errorf("failed to write transcript: %w", err)
179→	}
180→
181→	return nil
182→}
183→
184→// FormatResumeCommand returns the command to resume a Gemini CLI session.
185→func (g *GeminiCLIAgent) FormatResumeCommand(sessionID string) string {
186→	return "gemini --resume " + sessionID
187→}
188→
189→// GetProjectHash generates a unique hash for a project based on its root path.
190→// This matches Gemini CLI's getProjectHash() which uses SHA256 of the project root.
191→func GetProjectHash(projectRoot string) string {
192→	hash := sha256.Sum256([]byte(projectRoot))
193→	return hex.EncodeToString(hash[:])
194→}
195→
196→// TranscriptAnalyzer interface implementation
197→
198→// GetTranscriptPosition returns the current message count of a Gemini transcript.
199→// Gemini uses JSON format with a messages array, so position is the message count.
200→// Returns 0 if the file doesn't exist or is empty.
201→func (g *GeminiCLIAgent) GetTranscriptPosition(path string) (int, error) {
202→	if path == "" {
203→		return 0, nil
204→	}
205→
206→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
207→	if err != nil {
208→		if os.IsNotExist(err) {
209→			return 0, nil
210→		}
211→		return 0, fmt.Errorf("failed to read transcript: %w", err)
212→	}
213→
214→	if len(data) == 0 {
215→		return 0, nil
216→	}
217→
218→	transcript, err := ParseTranscript(data)
219→	if err != nil {
220→		return 0, fmt.Errorf("failed to parse transcript: %w", err)
221→	}
222→
223→	return len(transcript.Messages), nil
224→}
225→
226→// ExtractModifiedFilesFromOffset extracts files modified since a given message index.
227→// For Gemini (JSON format), offset is the starting message index.
228→// Returns:
229→//   - files: list of file paths modified by Gemini (from Write/Edit tools)
230→//   - currentPosition: total number of messages in the transcript
231→//   - error: any error encountered during reading
232→func (g *GeminiCLIAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
233→	if path == "" {
234→		return nil, 0, nil
235→	}
236→
237→	data, readErr := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
238→	if readErr != nil {
239→		if os.IsNotExist(readErr) {
240→			return nil, 0, nil
241→		}
242→		return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
243→	}
244→
245→	if len(data) == 0 {
246→		return nil, 0, nil
247→	}
248→
249→	transcript, parseErr := ParseTranscript(data)
250→	if parseErr != nil {
251→		return nil, 0, parseErr
252→	}
253→
254→	totalMessages := len(transcript.Messages)
255→
256→	// Extract files from messages starting at startOffset
257→	fileSet := make(map[string]bool)
258→	for i := startOffset; i < len(transcript.Messages); i++ {
259→		msg := transcript.Messages[i]
260→		// Only process gemini messages (assistant messages)
261→		if msg.Type != MessageTypeGemini {
262→			continue
263→		}
264→
265→		// Process tool calls in this message
266→		for _, toolCall := range msg.ToolCalls {
267→			// Check if it's a file modification tool
268→			isModifyTool := false
269→			for _, name := range FileModificationTools {
270→				if toolCall.Name == name {
271→					isModifyTool = true
272→					break
273→				}
274→			}
275→
276→			if !isModifyTool {
277→				continue
278→			}
279→
280→			// Extract file path from args map
281→			var file string
282→			if fp, ok := toolCall.Args["file_path"].(string); ok && fp != "" {
283→				file = fp
284→			} else if p, ok := toolCall.Args["path"].(string); ok && p != "" {
285→				file = p
286→			} else if fn, ok := toolCall.Args["filename"].(string); ok && fn != "" {
287→				file = fn
288→			}
289→
290→			if file != "" && !fileSet[file] {
291→				fileSet[file] = true
292→				files = append(files, file)
293→			}
294→		}
295→	}
296→
297→	return files, totalMessages, nil
298→}
299→
300→// ChunkTranscript splits a Gemini JSON transcript by distributing messages across chunks.
301→// Gemini uses JSON format with a {"messages": [...]} structure, so chunking splits
302→// the messages array while preserving the JSON structure in each chunk.
303→func (g *GeminiCLIAgent) ChunkTranscript(ctx context.Context, content []byte, maxSize int) ([][]byte, error) {
304→	var transcript GeminiTranscript
305→	if err := json.Unmarshal(content, &transcript); err != nil {
306→		// Fall back to JSONL chunking if not valid Gemini JSON
307→		chunks, chunkErr := agent.ChunkJSONL(content, maxSize)
308→		if chunkErr != nil {
309→			return nil, fmt.Errorf("failed to chunk as JSONL: %w", chunkErr)
310→		}
311→		return chunks, nil
312→	}
313→
314→	if len(transcript.Messages) == 0 {
315→		return [][]byte{content}, nil
316→	}
317→
318→	var chunks [][]byte
319→	var currentMessages []GeminiMessage
320→	currentSize := len(`{"messages":[]}`) // Base JSON structure size
321→
322→	for i, msg := range transcript.Messages {
323→		// Marshal message to get its size
324→		msgBytes, err := json.Marshal(msg)
325→		if err != nil {
326→			logging.Warn(ctx, "failed to marshal Gemini message during chunking",
327→				slog.Int("message_index", i),
328→				slog.String("error", err.Error()),
329→			)
330→			continue
331→		}
332→		msgSize := len(msgBytes) + 1 // +1 for comma separator
333→
334→		if currentSize+msgSize > maxSize && len(currentMessages) > 0 {
335→			// Save current chunk
336→			chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
337→			if err != nil {
338→				return nil, fmt.Errorf("failed to marshal chunk: %w", err)
339→			}
340→			chunks = append(chunks, chunkData)
341→
342→			// Start new chunk
343→			currentMessages = nil
344→			currentSize = len(`{"messages":[]}`)
345→		}
346→
347→		currentMessages = append(currentMessages, msg)
348→		currentSize += msgSize
349→	}
350→
351→	// Add the last chunk
352→	if len(currentMessages) > 0 {
353→		chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
354→		if err != nil {
355→			return nil, fmt.Errorf("failed to marshal final chunk: %w", err)
356→		}
357→		chunks = append(chunks, chunkData)
358→	}
359→
360→	// Ensure we created at least one chunk (could be empty if all messages failed to marshal)
361→	if len(chunks) == 0 {
362→		return nil, errors.New("failed to create any chunks: all messages failed to marshal")
363→	}
364→
365→	return chunks, nil
366→}
367→
368→// ReassembleTranscript merges Gemini JSON chunks by combining their message arrays.
369→func (g *GeminiCLIAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
370→	var allMessages []GeminiMessage
371→
372→	for _, chunk := range chunks {
373→		var transcript GeminiTranscript
374→		if err := json.Unmarshal(chunk, &transcript); err != nil {
375→			return nil, fmt.Errorf("failed to unmarshal chunk: %w", err)
376→		}
377→		allMessages = append(allMessages, transcript.Messages...)
378→	}
379→
380→	result, err := json.Marshal(GeminiTranscript{Messages: allMessages})
381→	if err != nil {
382→		return nil, fmt.Errorf("failed to marshal reassembled transcript: %w", err)
383→	}
384→	return result, nil
385→}
