  1→package strategy
  2→
  3→import (
  4→	"context"
  5→	"fmt"
  6→	"log/slog"
  7→	"os"
  8→	"path/filepath"
  9→	"strings"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 12→	"github.com/entireio/cli/cmd/entire/cli/logging"
 13→	"github.com/entireio/cli/cmd/entire/cli/paths"
 14→	"github.com/entireio/cli/cmd/entire/cli/session"
 15→	"github.com/entireio/cli/cmd/entire/cli/validation"
 16→)
 17→
 18→// Session state management functions shared across all strategies.
 19→// SessionState is stored in .git/entire-sessions/{session_id}.json
 20→
 21→// getSessionStateDir returns the path to the session state directory.
 22→// This is stored in the git common dir so it's shared across all worktrees.
 23→func getSessionStateDir(ctx context.Context) (string, error) {
 24→	commonDir, err := GetGitCommonDir(ctx)
 25→	if err != nil {
 26→		return "", err
 27→	}
 28→	return filepath.Join(commonDir, session.SessionStateDirName), nil
 29→}
 30→
 31→// sessionStateFile returns the path to a session state file.
 32→func sessionStateFile(ctx context.Context, sessionID string) (string, error) {
 33→	stateDir, err := getSessionStateDir(ctx)
 34→	if err != nil {
 35→		return "", err
 36→	}
 37→	return filepath.Join(stateDir, sessionID+".json"), nil
 38→}
 39→
 40→// LoadSessionState loads the session state for the given session ID.
 41→// Returns (nil, nil) when session file doesn't exist or session is stale (not an error condition).
 42→// Stale sessions are automatically deleted by the underlying StateStore.
 43→func LoadSessionState(ctx context.Context, sessionID string) (*SessionState, error) {
 44→	store, err := session.NewStateStore(ctx)
 45→	if err != nil {
 46→		return nil, fmt.Errorf("failed to create state store: %w", err)
 47→	}
 48→
 49→	state, err := store.Load(ctx, sessionID)
 50→	if err != nil {
 51→		return nil, fmt.Errorf("failed to load session state: %w", err)
 52→	}
 53→	return state, nil
 54→}
 55→
 56→// SaveSessionState saves the session state atomically.
 57→func SaveSessionState(ctx context.Context, state *SessionState) error {
 58→	// Validate session ID to prevent path traversal
 59→	if err := validation.ValidateSessionID(state.SessionID); err != nil {
 60→		return fmt.Errorf("invalid session ID: %w", err)
 61→	}
 62→
 63→	stateDir, err := getSessionStateDir(ctx)
 64→	if err != nil {
 65→		return fmt.Errorf("failed to get session state directory: %w", err)
 66→	}
 67→
 68→	if err := os.MkdirAll(stateDir, 0o750); err != nil {
 69→		return fmt.Errorf("failed to create session state directory: %w", err)
 70→	}
 71→
 72→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
 73→	if err != nil {
 74→		return fmt.Errorf("failed to marshal session state: %w", err)
 75→	}
 76→
 77→	stateFile, err := sessionStateFile(ctx, state.SessionID)
 78→	if err != nil {
 79→		return fmt.Errorf("failed to get session state file path: %w", err)
 80→	}
 81→
 82→	// Atomic write: write to temp file, then rename
 83→	tmpFile := stateFile + ".tmp"
 84→	if err := os.WriteFile(tmpFile, data, 0o600); err != nil {
 85→		return fmt.Errorf("failed to write session state: %w", err)
 86→	}
 87→	if err := os.Rename(tmpFile, stateFile); err != nil {
 88→		return fmt.Errorf("failed to rename session state file: %w", err)
 89→	}
 90→	return nil
 91→}
 92→
 93→// ListSessionStates returns all session states from the state directory.
 94→// This is a package-level function that doesn't require a specific strategy instance.
 95→func ListSessionStates(ctx context.Context) ([]*SessionState, error) {
