 24→// resolveTranscriptPath determines the correct file path for an agent's session transcript.
 25→// Computes the path dynamically from the current repo location for cross-machine portability.
 26→func resolveTranscriptPath(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
 27→	repoRoot, err := paths.WorktreeRoot(ctx)
 28→	if err != nil {
 29→		return "", fmt.Errorf("failed to get worktree root: %w", err)
 30→	}
 31→
 32→	sessionDir, err := agent.GetSessionDir(repoRoot)
 33→	if err != nil {
 34→		return "", fmt.Errorf("failed to get agent session directory: %w", err)
 35→	}
 36→	return agent.ResolveSessionFile(sessionDir, sessionID), nil
 37→}
