 39→// agentSessionBaseDirs maps agent names to the base directories that contain
 40→// per-project session subdirectories. Each agent organizes transcripts under
 41→// a per-project subdirectory within its base dir.
 42→var agentSessionBaseDirs = map[types.AgentName]func() (string, error){
 43→	agentpkg.AgentNameClaudeCode: func() (string, error) {
 44→		home, err := os.UserHomeDir()
 45→		if err != nil {
 46→			return "", fmt.Errorf("failed to get home directory: %w", err)
 47→		}
 48→		return filepath.Join(home, ".claude", "projects"), nil
 49→	},
 50→	agentpkg.AgentNameGemini: func() (string, error) {
 51→		home, err := os.UserHomeDir()
 52→		if err != nil {
 53→			return "", fmt.Errorf("failed to get home directory: %w", err)
 54→		}
 55→		return filepath.Join(home, ".gemini", "tmp"), nil
 56→	},
 57→}
