 59→// searchTranscriptInProjectDirs searches for a session transcript across all of an agent's
 60→// project directories. Agents like Claude Code and Gemini CLI use the cwd to determine the
 61→// project directory, so the transcript may be stored under a different project directory
 62→// if the session was started from a different working directory.
 63→func searchTranscriptInProjectDirs(agentName types.AgentName, sessionID string, ag agentpkg.Agent) (string, error) {
 64→	baseDirFn, ok := agentSessionBaseDirs[agentName]
 65→	if !ok {
 66→		return "", fmt.Errorf("fallback transcript search not supported for agent %q", agentName)
 67→	}
 68→	baseDir, err := baseDirFn()
 69→	if err != nil {
 70→		return "", fmt.Errorf("failed to get base directory: %w", err)
 71→	}
 72→
 73→	// Walk all subdirectories looking for the session file.
 74→	// Agents like Gemini nest chats under <project>/chats/, so we need recursive search.
 75→	var found string
 76→	walkErr := filepath.WalkDir(baseDir, func(path string, d os.DirEntry, err error) error {
 77→		if err != nil || !d.IsDir() {
 78→			return nil //nolint:nilerr // skip inaccessible dirs
 79→		}
 80→		candidate := ag.ResolveSessionFile(path, sessionID)
 81→		if _, statErr := os.Stat(candidate); statErr == nil {
 82→			found = candidate
 83→			return filepath.SkipAll
 84→		}
 85→		return nil
 86→	})
 87→	if walkErr != nil {
 88→		return "", fmt.Errorf("failed to search project directories: %w", walkErr)
 89→	}
 90→	if found != "" {
 91→		return found, nil
 92→	}
 93→	return "", errors.New("transcript not found in any project directory")
 94→}
