 24→// GeminiMessage represents a single message in the transcript
 25→type GeminiMessage struct {
 26→	ID        string           `json:"id,omitempty"` // UUID for the message
 27→	Type      string           `json:"type"`         // MessageTypeUser or MessageTypeGemini
 28→	Content   string           `json:"content,omitempty"`
 29→	ToolCalls []GeminiToolCall `json:"toolCalls,omitempty"`
 30→}
