318→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
319→// When force is true, it amends without prompting.
320→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
321→	// Get HEAD commit info
322→	repo, err := openRepository(ctx)
323→	if err != nil {
324→		return fmt.Errorf("failed to open repository: %w", err)
325→	}
326→	headRef, err := repo.Head()
327→	if err != nil {
328→		return fmt.Errorf("failed to get HEAD: %w", err)
329→	}
330→	headCommit, err := repo.CommitObject(headRef.Hash())
331→	if err != nil {
332→		return fmt.Errorf("failed to get HEAD commit: %w", err)
333→	}
334→
335→	shortHash := headRef.Hash().String()[:7]
336→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
337→
338→	// Check if the commit already has this checkpoint trailer
339→	if _, found := trailers.ParseCheckpoint(headCommit.Message); found {
340→		fmt.Fprintf(w, "\nLast commit already has an Entire-Checkpoint trailer.\n")
341→		return nil
342→	}
343→
344→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
345→
346→	amend := true
347→	if !force {
348→		form := NewAccessibleForm(
349→			huh.NewGroup(
350→				huh.NewConfirm().
351→					Title("Amend the last commit in this branch?").
352→					Affirmative("Y").
353→					Negative("n").
354→					Value(&amend),
355→			),
356→		)
357→		if err := form.Run(); err != nil {
358→			return fmt.Errorf("prompt failed: %w", err)
359→		}
360→	}
361→
362→	if !amend {
363→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
364→		return nil
365→	}
366→
367→	// Amend the commit with the checkpoint trailer
368→	newMessage := fmt.Sprintf("%s\n\n%s: %s\n", strings.TrimRight(headCommit.Message, "\n"), trailers.CheckpointTrailerKey, checkpointIDStr)
369→
370→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "-m", newMessage)
371→	if output, err := cmd.CombinedOutput(); err != nil {
372→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
373→	}
374→
375→	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
376→	return nil
377→}
