 27→// GeminiCLIAgent implements the Agent interface for Gemini CLI.
 28→//
 29→//nolint:revive // GeminiCLIAgent is clearer than Agent in this context
 30→type GeminiCLIAgent struct{}
 31→
 32→func NewGeminiCLIAgent() agent.Agent {
 33→	return &GeminiCLIAgent{}
 34→}
