			// Gemini CLI hooks only fire correctly when started from the repo root.
			// If the transcript is in a different project directory, the session was started
			// from a subdirectory where SessionEnd (and other hooks) won't execute properly,
			// resulting in incomplete metadata. Reject the attach in this case.
			if agentType == agent.AgentTypeGemini {
				return "", fmt.Errorf("session %s appears to have been started from a different directory than the repository root; "+
					"Gemini CLI hooks do not fire correctly when started from subdirectories, "+
					"so the session metadata would be incomplete and cannot be attached", sessionID)
			}
			logging.Info(ctx, "found transcript in alternative project directory", "path", found)
			transcriptPath = found
		} else {
			logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
		}
	}
	if _, statErr := os.Stat(transcriptPath); statErr != nil {
		return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", agentName, sessionID)
	}
	return transcriptPath, nil
}

